-- ════════════════════════════════════════════════════════════════════════
-- Hearthrise — THE TRADES: TOWN WORK ON ONE CURVE, AND ITS FORMULA TWINS  (GENERATED — DO NOT EDIT)
--
--   Generated by tools/gen-trades.mjs from src/core/trades.js (the rule) and src/data/trades.js (TRADE_LEVERS, TRADES, KINDS), with
--   src/data/store-kit.js (kitWork, townWageShare, storeCeiling, the meal and charge shares), src/data/gear-steps.js (tierSteps) and
--   src/data/danger.js (powerStep). Any hand edit FAILS `node tools/gen-trades.mjs --check`.
--
-- WHAT (lane/trade-formulas, backend-architect, 2026-11-22; 09-crafting.md section 4, built in 4.8; 13-market.md section 3.2): the trades'
-- catalogue and every formula the server needs to price, check and settle town work, so no number is typed twice.
--   hr_trade_levers   1 row: the levers as whole numbers.
--   hr_trade_kinds    37 kinds (24 ship in v0.3.0, 13 later), upserted: work in micro-hours (V's) and an attempt's own
--                     work, inputs { kind: n } and hunted inputs { stream: permille of an hour-unit }. A RECIPE is (kind, rung): rung r opens
--                     at trade Level 1 + (r - 1) x 10 (350 recipes); its band is the job's.
--   hr_trade_xp       99 rows: XP (seconds of work) to reach each trade Level; 1000 hours to 99.
--   twins (internal)  the curve (yield, Fine, Master, speed, XP factor), the Level from XP, V and the job fee, the store's step, ask and bid,
--                     the contest curve behind a band, a tool's speed, life and rent, and the job's bound; each pinned to the JS (§4).
--   THE JOB SLICE (lane/k1-job-slice, 2026-11-26; 09 sections 4.9 and 6):
--   hr_trade_recipes  82 recipes a job may run (src/core/trades.js jobRecipes: the named kit recipes and the imbuement jobs): kind,
--                     trade, band, rung, opening Level, face, and inputs as whole goods a set. A recipe not here is refused bad_recipe.
--   hr_trade_ground_bands  16 Danger scale grounds and their band (gearLevel / tierSteps): a depth record there opens its band.
--   twins (internal)  hr_trade_band_rung (bandRung), hr_trade_mulberry (src/core/rng.js mulberry32's draw) and hr_trade_roll (settleJob, line
--                     for line), pinned EXACTLY at 341 jobs, so the server settles a job from its stored seed itself.
-- READERS: 1073-k1-job-slice.sql (hr_trade_job_start, its settle and the `trade_jobs` section). The live town work (hr_activities, the old
-- rows) is untouched.
-- ORDER: 1063 in its name, after 1058-hunting-blocks-catalogue.generated.sql (hr_wage, which V reads). Idempotent: the tables are made if
-- missing and their rows upserted (a kind or recipe the data no longer has is deleted), the functions restated, so a second apply is byte-identical. No begin/commit (CLAUDE.md §2).
-- EXPLOIT SURFACE: none added. Five catalogue tables, RLS on, no policy, no grant to any client role; every twin revoked from every client
-- role and the engine's. No value moves here. ON THE PRE-EA SECURITY LIST (13-security-list.md S-10): V anchors the job fee, the store's
-- ask and bid and the market's bands; the recipe rows and the roller decide what a job takes and makes.
-- REVERSIBLE: drop the functions and the five tables.
-- ════════════════════════════════════════════════════════════════════════

-- ── §0 PRECONDITIONS ─────────────────────────────────────────────────────────
do $mig$
begin
  if to_regprocedure('public.hr_wage(integer)') is null then
    raise exception 'PRECONDITION: the wage first (1058-hunting-blocks-catalogue.generated.sql, hr_wage)'; end if;
end $mig$;

-- ── §1 THE TABLES ────────────────────────────────────────────────────────────
create table if not exists public.hr_trade_levers (
  id boolean primary key default true check (id),
  rung_count         int    not null check (rung_count >= 0),
  rung_span          int    not null check (rung_span >= 0),
  max_level          int    not null check (max_level >= 0),
  at_req_pm          int    not null check (at_req_pm >= 0),
  no_fail_span       int    not null check (no_fail_span >= 0),
  cap_pm             int    not null check (cap_pm >= 0),
  mastery_return_pm  int    not null check (mastery_return_pm >= 0),
  bench_max_pm       int    not null check (bench_max_pm >= 0),
  fine_base_pm       int    not null check (fine_base_pm >= 0),
  fine_top_pm        int    not null check (fine_top_pm >= 0),
  master_top_pm      int    not null check (master_top_pm >= 0),
  quality_steps      int    not null check (quality_steps >= 0),
  speed_at99_pm      int    not null check (speed_at99_pm >= 0),
  xp_window          int    not null check (xp_window >= 0),
  xp_floor_pm        int    not null check (xp_floor_pm >= 0),
  job_fee_pm         int    not null check (job_fee_pm >= 0),
  town_wage_share_pm int    not null check (town_wage_share_pm >= 0),
  store_ceiling_pm   int    not null check (store_ceiling_pm >= 0),
  store_lag          int    not null check (store_lag >= 0),
  floor_share_pm     int    not null check (floor_share_pm >= 0),
  store_budget_pm    int    not null check (store_budget_pm >= 0),
  tool_ms            bigint not null check (tool_ms >= 0),
  tool_life_rung_pm  int    not null check (tool_life_rung_pm >= 0),
  tier_steps         int    not null check (tier_steps >= 0),
  quality_live       int    not null check (quality_live between 0 and 1),
  crop_xp            int    not null check (crop_xp >= 0),
  power_step         float8 not null check (power_step > 0 and power_step < 0.05),
  check (at_req_pm < cap_pm and cap_pm >= 1000 and fine_top_pm >= fine_base_pm and floor_share_pm < store_ceiling_pm)
);
create table if not exists public.hr_trade_kinds (
  kind     text   primary key check (kind ~ '^[a-z][a-z0-9_]{1,31}$'),
  trade    text   not null check (trade ~ '^[a-z]{1,16}$'),
  stage    text   not null check (stage in ('gather', 'refine', 'make')),
  line     text   check (line in ('meal', 'charge', 'draught', 'imbuement')),
  opens    int    not null check (opens >= 1),
  ships    text   not null check (ships in ('v030', 'later')),
  rolls    text   check (rolls in ('step', 'life')),
  life_pm  int    not null check (life_pm between 0 and 1000),
  final    boolean not null,
  work_uh  bigint not null check (work_uh >= 1),
  own_uh   bigint not null check (own_uh >= 1 and own_uh <= work_uh),
  inputs   jsonb  not null check (jsonb_typeof(inputs) = 'object'),
  hunted   jsonb  not null check (jsonb_typeof(hunted) = 'object')
);
create table if not exists public.hr_trade_xp (
  level int    primary key check (level between 1 and 99),
  xp    bigint not null check (xp >= 0)
);
create table if not exists public.hr_trade_recipes (
  recipe  text   primary key check (recipe ~ '^[a-z][a-z0-9_]{1,63}$'),
  kind    text   not null references public.hr_trade_kinds (kind),
  trade   text   not null check (trade ~ '^[a-z]{1,16}$'),
  band    int    not null check (band >= 0),
  rung    int    not null check (rung >= 1),
  r_level int    not null check (r_level >= 1),
  face    text   not null check (face ~ '^[a-z0-9_]{1,64}$'),
  name    text   not null check (length(name) between 3 and 48),
  inputs  jsonb  not null check (jsonb_typeof(inputs) = 'object'),
  imbue   text
);
create table if not exists public.hr_trade_ground_bands (
  hunt_id text primary key check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  band    int  not null check (band >= 0)
);
alter table public.hr_trade_levers enable row level security;
alter table public.hr_trade_kinds enable row level security;
alter table public.hr_trade_xp enable row level security;
alter table public.hr_trade_recipes enable row level security;
alter table public.hr_trade_ground_bands enable row level security;
revoke all on public.hr_trade_levers, public.hr_trade_kinds, public.hr_trade_xp, public.hr_trade_recipes, public.hr_trade_ground_bands from public, anon, authenticated, service_role;
comment on table public.hr_trade_levers is '1063-trade-formulas-catalogue.generated.sql: the trades'' levers as whole numbers (src/data/trades.js through tools/gen-trades.mjs).';
comment on table public.hr_trade_kinds is '1063-trade-formulas-catalogue.generated.sql: one row a kind of good, its work and inputs derived by src/core/trades.js tradeCatalogue.';
comment on table public.hr_trade_xp is '1063-trade-formulas-catalogue.generated.sql: the XP (seconds of work) to reach each trade Level (src/core/trades.js tradeXpTable).';
comment on table public.hr_trade_recipes is '1063-trade-formulas-catalogue.generated.sql: the recipes a job may run (src/core/trades.js jobRecipes), inputs as whole goods a set.';
comment on table public.hr_trade_ground_bands is '1063-trade-formulas-catalogue.generated.sql: each Danger scale ground''s band (src/data/danger.js DANGER_GROUNDS gearLevel / tierSteps).';

-- ── §2 THE ROWS ──────────────────────────────────────────────────────────────
-- Upserted, never deleted and re-made: once the job slice points a row at a kind (a job, a stack), a catalogue change rewrites the kind
-- in place, and dropping a kind something still holds is refused by its key rather than taken silently.
insert into public.hr_trade_levers (id, rung_count, rung_span, max_level, at_req_pm, no_fail_span, cap_pm, mastery_return_pm, bench_max_pm, fine_base_pm, fine_top_pm, master_top_pm, quality_steps, speed_at99_pm, xp_window, xp_floor_pm, job_fee_pm, town_wage_share_pm, store_ceiling_pm, store_lag, floor_share_pm, store_budget_pm, tool_ms, tool_life_rung_pm, tier_steps, quality_live, crop_xp, power_step) values
  (true, 10, 10, 99, 750, 15, 1250, 100, 100, 100, 600, 500, 5, 1250, 20, 250, 250, 250, 1500, 20, 400, 1000, 43200000, 250, 20, 0, 252, '0.0035'::float8)
on conflict (id) do update set rung_count = excluded.rung_count, rung_span = excluded.rung_span, max_level = excluded.max_level, at_req_pm = excluded.at_req_pm, no_fail_span = excluded.no_fail_span, cap_pm = excluded.cap_pm, mastery_return_pm = excluded.mastery_return_pm, bench_max_pm = excluded.bench_max_pm, fine_base_pm = excluded.fine_base_pm, fine_top_pm = excluded.fine_top_pm, master_top_pm = excluded.master_top_pm, quality_steps = excluded.quality_steps, speed_at99_pm = excluded.speed_at99_pm, xp_window = excluded.xp_window, xp_floor_pm = excluded.xp_floor_pm, job_fee_pm = excluded.job_fee_pm, town_wage_share_pm = excluded.town_wage_share_pm, store_ceiling_pm = excluded.store_ceiling_pm, store_lag = excluded.store_lag, floor_share_pm = excluded.floor_share_pm, store_budget_pm = excluded.store_budget_pm, tool_ms = excluded.tool_ms, tool_life_rung_pm = excluded.tool_life_rung_pm, tier_steps = excluded.tier_steps, quality_live = excluded.quality_live, crop_xp = excluded.crop_xp, power_step = excluded.power_step;
